const N=[{"src": "zhaikpress.kz", "date": "2026-10-12", "url": "https://zhaikpress.kz/ru/news/kazaxstan-voshyol-v-chetvyorku-silnejshix-na-first-global-challenge-2026/", "img": "assets/img/nwi-nw-fgc-2026-team.jpg", "pos": "50% 45%", "t": ["FIRST Global Challenge 2026, Инчхон: Казахстан в четвёрке сильнейших", "FIRST Global Challenge 2026, Инчхон: Қазақстан үздік төрттікте", "FIRST Global Challenge 2026, Incheon: Kazakhstan in the top four"], "p": ["Сборная Казахстана выиграла все 11 матчей отборочного раунда, вышла в плей-офф и заняла 4-е место среди команд из 185 стран.", "Қазақстан құрамасы іріктеу кезеңіндегі 11 матчтың бәрінде жеңіп, плей-оффқа шықты және 185 елдің командалары арасында 4-орын алды.", "Team Kazakhstan won all 11 qualification matches, reached the playoffs and finished 4th among teams from 185 countries."]}, {"src": "Kazinform", "date": "2026-08-19", "url": "https://qazinform.com/news/kazakhstan-wins-23-awards-first-lego-league-asia-open-championship-in-beijing-9edca2", "img": "assets/img/x-nw-fll-asia-open-2026.jpg", "pos": "50% 45%", "t": ["FIRST LEGO League Asia Open 2026, Пекин: команды Казахстана завоевали 23 награды", "FIRST LEGO League Asia Open 2026, Бейжің: Қазақстан командалары 23 марапат алды", "FIRST LEGO League Asia Open 2026, Beijing: Kazakhstan's teams win 23 awards"], "p": ["13–16 августа в Пекине соревновались 375 команд из 25 стран и регионов. Команды Казахстана получили 3 серебряные, 5 бронзовых и 15 специальных наград.", "13–16 тамызда Бейжіңде 25 ел мен өңірден 375 команда бақ сынады. Қазақстан командалары 3 күміс, 5 қола және 15 арнайы марапат алды.", "On 13–16 August, 375 teams from 25 countries and regions competed in Beijing. Kazakhstan's teams won 3 silver, 5 bronze and 15 special awards."]}, {"src": "Kazinform", "date": "2026-05-13", "url": "https://inform.kz/ru/kazahstanskie-shkolniki-stali-prizerami-chempionata-po-robototehnike-v-gretsii-904311b9", "img": "assets/img/x-nw-first-table.jpg", "pos": "50% 50%", "t": ["Команда Qazygurt стала призёром международного чемпионата в Греции", "Qazygurt командасы Грекиядағы халықаралық чемпионатта жүлдегер атанды", "Team Qazygurt wins an award at an international championship in Greece"], "p": ["Команда Qazygurt из Туркестанской области заняла 2-е место в номинации Champions Award на Open International Championship 2026 в Коринфе. Путёвку она получила по итогам Alem Tech Fest.", "Түркістан облысының Qazygurt командасы Коринфте өткен Open International Championship 2026-да Champions Award номинациясында екінші орын алды. Жолдаманы Alem Tech Fest қорытындысы бойынша алды.", "Team Qazygurt from Turkistan Region took second place in the Champions Award category at the Open International Championship 2026 in Corinth. The team qualified through Alem Tech Fest."]}, {"src": "Kazinform", "date": "2026-05-04", "url": "https://www.inform.kz/ru/sbornaya-kazahstana-zavoevala-12-nagrad-na-chempionate-mira-po-robototehnike-v-h-abe020c1", "img": "assets/img/ph3.jpg", "pos": "50% 50%", "t": ["FIRST Championship 2026, Хьюстон: команды Казахстана завоевали 12 наград", "FIRST Championship 2026, Хьюстон: Қазақстан командалары 12 марапат алды", "FIRST Championship 2026, Houston: Kazakhstan teams win 12 awards"], "p": ["В чемпионате мира в Хьюстоне участвовали 17 команд — рекордная делегация из 225 школьников. Результаты стали возможны при поддержке Министерства просвещения РК, USTEM Foundation и РНПЦ «Дарын».", "Хьюстондағы әлем чемпионатына 17 команда — 225 оқушыдан тұратын рекордтық делегация барды. Бұл нәтижеге ҚР Оқу-ағарту министрлігінің, USTEM Foundation-ның және «Дарын» РҒПО-ның қолдауымен қол жеткізілді.", "A record delegation of 17 teams and 225 students took part in the world championship in Houston. The results were made possible with support from the Ministry of Education of Kazakhstan, USTEM Foundation and the Daryn National Center."]}, {"src": "The Astana Times", "date": "2026-02-12", "url": "https://astanatimes.com/2026/02/alem-tech-fest-brings-central-asias-young-innovators-to-astana/", "img": "assets/img/x-nw-alem-tech-fest.jpg", "pos": "50% 35%", "t": ["Alem Tech Fest 2026: 5 000 школьников из 7 стран в Астане", "Alem Tech Fest 2026: Астанада 7 елден 5 000 оқушы", "Alem Tech Fest 2026: 5,000 school students from 7 countries in Astana"], "p": ["11–13 февраля на площадке EXPO прошёл крупнейший в Центральной Азии фестиваль робототехники и STEM. 50 лучших команд получили путёвки на международные турниры FIRST, в том числе на чемпионат мира в Хьюстоне.", "11–13 ақпанда EXPO алаңында Орталық Азиядағы ең ірі робототехника және STEM фестивалі өтті. 50 үздік команда FIRST халықаралық турнирлеріне, соның ішінде Хьюстондағы әлем чемпионатына жолдама алды.", "On 11–13 February, Central Asia's largest robotics and STEM festival took place at EXPO. The top 50 teams qualified for international FIRST competitions, including the world championship in Houston."]}, {"src": "gov.kz", "date": "2025-11-02", "url": "https://www.gov.kz/memleket/entities/edu/press/news/details/1097414?lang=ru", "img": "assets/img/x-nw-hero.jpg", "pos": "50% 30%", "t": ["Четвёртая победа. Казахстан — снова чемпион мира", "Төртінші жеңіс. Қазақстан — тағы да әлем чемпионы", "A fourth victory: Kazakhstan is world champion again"], "p": ["В Панама-Сити сборная Казахстана победила на FIRST Global Challenge 2025 и получила золотые награды Grand Challenge Award и Albert Einstein Award.", "Панама-Ситиде Қазақстан құрамасы FIRST Global Challenge 2025-те жеңіп, Grand Challenge Award және Albert Einstein Award алтын марапаттарын иеленді.", "In Panama City, Team Kazakhstan won the FIRST Global Challenge 2025, taking gold with the Grand Challenge Award and the Albert Einstein Award."]}];
